protocol Card { func summary() -> String }
struct IDCard: Card {
    let id: Int
    func summary() -> String { "Проект \(id)" }
}
struct NameCard: Card {
    let name: String
    func summary() -> String { name }
}
func chooseCard(showID: Bool) -> any Card {
    if showID { return IDCard(id: 71) }
    return NameCard(name: "Фото")
}
let cards: [any Card] = [
    chooseCard(showID: true), chooseCard(showID: false)
]
for card in cards { print(card.summary()) }

Existential-возврат допускает два разных конкретных типа; обычный some-возврат здесь не компилируется.

func total(_ values: any Collection<Int>) -> Int {
    values.reduce(0, +)
}
print(total([71, 72]))
print(total(Set([71, 72])))

Элементы обеих коллекций известны как Int. Не требуется одна и та же конкретная коллекция.

protocol Feed {
    associatedtype Item
    func first() -> Item?
}
struct IDFeed: Feed {
    typealias Item = Int
    let ids: [Int]
    func first() -> Int? { ids.first }
}
struct NameFeed: Feed {
    let names: [String]
    func first() -> String? { names.first }
}
func firstID<F: Feed>(_ feed: F) -> Int? where F.Item == Int {
    feed.first()
}
print(firstID(IDFeed(ids: [71, 72])) ?? 0)
print(firstID(IDFeed(ids: [])) == nil)

Связь Item == Int проверяется на уровне generic-функции.
